import { Effect } from "effect"

export interface Shipment {
  readonly trackingId: string
  readonly status: "queued" | "dispatched" | "delivered"
  readonly weightGrams: number
}

export interface DispatchSummary {
  readonly shipmentCount: number
  readonly totalWeightGrams: number
}

const selectDispatched = (shipments: ReadonlyArray<Shipment>) =>
  shipments.filter((shipment) => shipment.status === "dispatched")

const summarize = (shipments: ReadonlyArray<Shipment>): DispatchSummary => ({
  shipmentCount: shipments.length,
  totalWeightGrams: shipments.reduce(
    (total, shipment) => total + shipment.weightGrams,
    0
  )
})

export const buildDispatchSummary = (
  shipments: ReadonlyArray<Shipment>
): Effect.Effect<DispatchSummary> =>
  Effect.succeed(shipments).pipe(
    Effect.map(selectDispatched),
    Effect.map(summarize)
  )
